 */

public function receive(Request $request, string $provider)
{
    if (preg_match('/^[a-z0-9][a-z0-9_-]{0,63}$/', $provider) !== 1) {
        return response()->json(['error' => 'Webhook endpoint not found'], 404);
    }

    $registry = $this->adapters ?? app(IntegrationAdapterRegistry::class);
    $publisher = $this->outbox ?? app(MonitoringOutboxPublisher::class);
    $bindings = $this->bindings ?? app(ProviderWebhookBindingGuard::class);

    try {
        $capability = $registry->capability($provider, WebhookVerificationCapability::class);
    } catch (CapabilityUnavailable|\RuntimeException) {
        return response()->json(['error' => 'Webhook endpoint not found'], 404);
    }

    if (! $capability instanceof WebhookVerificationCapability) {
        return response()->json(['error' => 'Webhook endpoint not found'], 404);
    }

    try {
        $providerConnection = IntegrationProviderConnection::query()
            ->forProvider($provider)
            ->connected()
            ->first();
        if ($providerConnection === null) {
            return response()->json(['error' => 'Webhook rejected'], 401);
        }

        $headers = [];
        foreach ([
            'X-Integration-Key',
            'X-Webhook-Timestamp',
            'X-Webhook-Nonce',
            'X-Webhook-Signature',
            'X-Msc-Request-Signature',
            'X-Msc-Webhook-Uuid',
            'X-Msc-Request-Timestamp',
            'X-Msc-Request-Nonce',
        ] as $name) {
            $value = $request->header($name);
            if (is_string($value)) {
                $headers[$name] = $value;
            }
        }

        $verified = $capability->verifyWebhook($providerConnection, new ProviderWebhookRequest(
            body: $request->getContent(),
            headers: $headers,
            receivedAt: CarbonImmutable::now('UTC'),
        ));

        $result = DB::transaction(function () use ($bindings, $provider, $providerConnection, $publisher, $verified): array {
            $activeConnection = IntegrationProviderConnection::query()
                ->whereKey($providerConnection->id)
                ->forProvider($provider)
                ->connected()
                ->sharedLock()
                ->first(['id']);
            if ($activeConnection === null) {
                return [
                    'connection_disabled' => true,
                    'message_ids' => [],
                    'duplicates' => 0,
                ];
            }

            $messageIds = [];
            $duplicates = 0;

            foreach ($verified->events as $event) {
                $bindings->assertActive(
                    provider: $provider,
                    providerConnectionId: (int) $activeConnection->id,
                    siteId: $event->siteId,
                    binding: $event->binding,
                );

                $existing = IntegrationEvent::query()
                    ->where('provider', $provider)
                    ->where('source_event_id', $event->sourceEventId)
                    ->lockForUpdate()
                    ->first();
                if ($existing !== null) {
                    if (! $this->existingEventMatches($existing, $event)) {
                        throw new WebhookRejected('source_identity_conflict', 404);
                    }
                    $duplicates++;

                    continue;
                }

                // Webhook identity is application-wide for a provider. Keeping
                // Site out of the source prevents the same provider identity
                // from splitting into concurrent per-Site outbox streams.
                $source = "provider:{$provider}:webhooks";
                $idempotencyKey = 'event:'.hash('sha256', $provider.':'.$event->sourceEventId);
                $outbox = $publisher->stage(
                    type: RuntimeMessageType::Event,
                    stream: (string) config('monitoring.queues.events', 'monitoring-events'),
                    source: $source,
                    idempotencyKey: $idempotencyKey,
                    payload: [
                        'event_family' => 'provider_event',
                        'site_id' => $event->siteId,
                        'provider' => $provider,
                        'source_app' => $event->sourceApp,
                        'source_event_id' => $event->sourceEventId,
                        'occurred_at' => $event->occurredAt->toIso8601String(),
                        'severity' => $event->severity,
                        'event_type' => $event->eventType,
                        'normalized_payload' => $event->normalizedPayload,
                        'body_hash' => $event->bodyHash,
                        'webhook_binding' => $event->binding->runtimePayload((int) $activeConnection->id),
                    ],
                );
                if ($outbox->wasRecentlyCreated) {
                    $messageIds[] = $outbox->message_id;
                } else {
                    $duplicates++;
                }
            }

            return [
                'connection_disabled' => false,
                'message_ids' => $messageIds,
                'duplicates' => $duplicates,
            ];
        });

        if ($result['connection_disabled']) {
            return response()->json(['error' => 'Webhook rejected'], 401);
        }

        $accepted = count($result['message_ids']);
        $response = [
            'status' => $accepted > 0 || $verified->ignoredCount > 0 ? 'accepted' : 'duplicate',
            'accepted' => $accepted,
            'duplicates' => $result['duplicates'],
            'ignored' => $verified->ignoredCount,
        ];
        if ($result['message_ids'] !== []) {
            $response['message_id'] = $result['message_ids'][0];
        }

        return response()->json(
            $response,
            $accepted > 0 || $verified->ignoredCount > 0
                ? $verified->acknowledgementStatus
                : 200,
        );
    } catch (WebhookRejected $exception) {
        Log::notice('Provider webhook rejected.', [
            'provider' => $provider,
            'reason_code' => $exception->reason,
        ]);

        return response()->json([
            'error' => $exception->httpStatus === 404
                ? 'Webhook endpoint not found'
                : 'Webhook rejected',
        ], $exception->httpStatus);
    } catch (WebhookBindingUnavailable|UnexpectedValueException) {
        Log::notice('Provider webhook binding rejected.', [
            'provider' => $provider,
            'reason_code' => 'binding_or_identity_conflict',
        ]);

        return response()->json(['error' => 'Webhook endpoint not found'], 404);
    } catch (\InvalidArgumentException) {
        return response()->json(['error' => 'Webhook rejected'], 422);
    } catch (\Throwable $e) {
        Log::error('Provider webhook intake failed.', SafeOperationalData::logContext([
            'provider' => $provider,
            'error_category' => SafeOperationalData::failureCategory($e),
        ]));

        return response()->json(['error' => 'Webhook intake failed'], 500);
    }
}

    public function show(Request $request, Client $client)
    {
        $this->authorize('view', $client);

        $user = $request->user();
        abort_unless($user, 403);
        $sectionAccessService = app(PortalClientSectionAccess::class);
        $sectionAccess = $sectionAccessService->for($user, $client);
        $canViewFamilyInformation = $sectionAccess['has_family_information_consent'];
        $canViewMedical = $sectionAccess['can_view_medical'];
        $canViewMedications = $sectionAccess['can_view_medications'];

        $clientRelations = [];
        if ($canViewMedical) {
            $clientRelations[] = 'medicalProfile';
            $clientRelations[] = 'conditions';
            $clientRelations[] = 'emergencyContacts';
        }
        if ($canViewMedications) {
            $clientRelations[] = 'medications';
        }
        $client->load($clientRelations);

        $documents = $canViewFamilyInformation
            ? ClientDocument::query()
                ->where('client_id', $client->id)
                ->where('portal_visible', true)
                ->orderByDesc('created_at')
                ->get(['id', 'title', 'category', 'notes', 'original_name', 'mime_type', 'size_bytes', 'created_at'])
            : collect();

        $eventsQuery = TimelineEvent::query()
            ->where('client_id', $client->id)
            ->where('visibility', 'portal')
            ->with(['actor:id,name', 'site:id,name']);
        $sectionAccessService->constrainTimeline($eventsQuery, $sectionAccess);
        $events = $eventsQuery->orderByDesc('occurred_at')
            ->limit(60)
            ->get();

        $incidents = collect();
        $canViewIncidents = $sectionAccess['can_view_incidents']
            && $user->canDo('incidents.view.portal');
        if ($canViewIncidents) {
            $incidents = ClientIncident::query()
                ->where('client_id', $client->id)
                ->where('portal_visible', true)
                ->whereNotNull('reviewed_at')
                ->orderByDesc('occurred_at')
                ->with(['attachments' => fn ($q) => $q->where('portal_visible', true)])
                ->limit(40)
                ->get();
        }

        $assets = $canViewFamilyInformation
            ? Asset::query()
                ->where('client_id', $client->id)
                ->orderBy('name')
                ->get(['id', 'name', 'asset_tag', 'status', 'risk_level'])
            : collect();

        $trackingConsent = $sectionAccessService->activeLocationTrackingConsent($client);

        $pageProps = [
            'client' => [
                'id' => $client->id,
                'first_name' => $client->first_name,
                'last_name' => $client->last_name,
                'profile_photo_url' => $client->profile_photo_url,
                'avatar' => $client->avatar,
            ],
            'documents' => $documents,
            'incidents' => $incidents->map(fn ($i) => [
                'id' => $i->id,
                'type' => $i->type,
                'severity' => $i->severity,
                'occurred_at' => optional($i->occurred_at)->toISOString(),
                'description' => $i->description,
                'immediate_action_taken' => $i->immediate_action_taken,
                'requires_followup' => (bool) $i->requires_followup,
                'attachments' => $i->attachments->map(fn ($a) => [
                    'id' => $a->id,
                    'original_name' => $a->original_name,
                    'mime_type' => $a->mime_type ?? $a->mime,
                    'size' => $a->size,
