            ] : null,
            'rag_answer' => session('rag_answer'),
            'can' => [
                'viewIncidents' => $canViewIncidents,
                'downloadIncidentAttachments' => $canViewIncidents
                    && $user->canDo('incidents.attachments.view.portal'),
                'askRag' => $sectionAccess['is_self']
