public function markRead(Request $request, string $notification)
{
    $user = $request->user();
    abort_unless($user, 403);

    $n = $user->notifications()->where('id', $notification)->firstOrFail();
    $n->markAsRead();

    // Keep UX snappy when called from header dropdown
    return back()->with('success', 'Notification marked as read.');
}

    public function acknowledge(Request $request, string $notification)
    {
        $user = $request->user();
        abort_unless($user, 403);

        $n = $user->notifications()->where('id', $notification)->firstOrFail();

        // Only acknowledge if this notification requests acknowledgement.
        $ackRequired = (bool) data_get($n->data, 'ack_required', false);
        if (!$ackRequired) {
            return back()->with('info', 'No acknowledgement required for this notification.');
        }

        if (is_null($n->acknowledged_at)) {
            $n->forceFill(['acknowledged_at' => now()])->save();
        }

        return back()->with('success', 'Notification acknowledged.');
    }
}

public function store(Request $request): RedirectResponse
{
    $validated = $request->validate([
        'attachable_type' => ['required', Rule::in(array_keys(self::TYPES))],
        'attachable_id' => ['required', 'integer'],
        'file' => ['required', 'file', 'max:10240', 'mimes:pdf,doc,docx,xls,xlsx,csv,txt,rtf,jpg,jpeg,png,gif,webp,heic'],
        'notes' => ['nullable', 'string', 'max:2000'],
        // Read via $request->boolean() — no strict rule so a multipart
        // "true"/"1"/"on" value isn't rejected.
        'is_sensitive' => ['nullable'],
    ]);

    [$class, , $writePerm] = self::TYPES[$validated['attachable_type']];
    abort_unless($request->user()?->canDo($writePerm), 403);

    $model = $class::findOrFail($validated['attachable_id']);

    $file = $request->file('file');
    $disk = 'private';
    $path = $file->store('privacy_attachments', $disk);

    $model->attachments()->create([
        'uploaded_by' => $request->user()?->id,
        'disk' => $disk,
        'original_name' => $file->getClientOriginalName(),
        'path' => $path,
        'mime' => $file->getClientMimeType(),
        'size' => $file->getSize(),
        'notes' => $validated['notes'] ?? null,
        'is_sensitive' => $request->boolean('is_sensitive'),
    ]);

    return back()->with('success', 'Document uploaded.');
}

public function execute(Request $request, RetentionExecutionService $service): RedirectResponse
{
    $this->authorizePermission($request);
    $validated = $request->validate([
        'policy_id' => ['required', 'integer', 'exists:data_retention_policies,id'],
        'confirm' => ['required', 'accepted'],
    ]);

    $policy = DataRetentionPolicy::query()->findOrFail($validated['policy_id']);

    try {
        $outcome = $service->execute($policy, 'manual', $request->user());
    } catch (RetentionContractException $exception) {
        return back()->with('error', $exception->getMessage());
    }

    if ($outcome['status'] === 'already_running') {
        return back()->with('info', 'This approved retention run is already in progress.');
    }

    if ($outcome['status'] === 'already_completed') {
        return back()->with('info', 'This approved retention run has already completed.');
    }

    if (in_array($outcome['status'], ['blocked', 'failed'], true)) {
        return back()->with(
            'error',
            $outcome['failure_message'] ?? 'This retention run did not complete. Review the governed execution log before retrying.',
        );
    }

    $result = $outcome['result'];
    $processed = (int) ($result['anonymized'] ?? 0)
        + (int) ($result['soft_deleted'] ?? 0)
        + (int) ($result['archived'] ?? 0);

    return back()->with(
        $processed > 0 ? 'success' : 'info',
        $processed > 0
            ? "Retention execution completed with {$processed} governed outcome(s)."
            : 'No eligible records remained after legal holds and exemptions were applied.',
    );
}

